from pathlib import Path
import json, html, shutil
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'dist'
DATA=json.loads((ROOT/'bank.json').read_text())
E=html.escape
BASE='https://omatty123.github.io/minds/'

def page(file,title,body):
 nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==file else '')+f'>{label}</a>' for p,label in [('index.html','The proposal'),('syllabus.html','Model syllabus'),('bank.html','Learning bank'),('participate.html','Take part')])
 doc=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | MIND(s)</title><meta name="description" content="An interdisciplinary proposal for First-Year Studies: a model syllabus and a source-linked learning bank on minds, feeling, skill and consciousness."><meta name="theme-color" content="#151515"><link rel="canonical" href="{BASE+file}"><meta property="og:title" content="{E(title)} | MIND(s)"><meta property="og:description" content="An open faculty proposal. Explore the model syllabus and learning bank."><meta property="og:type" content="website"><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="fonts.css"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="masthead"><div class="mast-inner"><a class="wordmark" href="index.html" aria-label="MIND(s) home">MIND<span>(s)</span></a><p>A proposal for<br class="brand-break"> First-Year Studies</p><span class="edition">Working edition<br>10 October 2026</span></div></header><nav class="nav" aria-label="Main navigation"><div>{nav}</div></nav><main id="main">{body}</main><footer><div><a class="footer-brand" href="index.html">MIND(s)</a><p>An independent faculty proposal for a future Lawrence University First-Year Studies theme.<br>Developed by Matty Wegehaupt. Not an adopted curriculum or institutional endorsement.</p></div><div class="footer-links"><a href="participate.html#editorial">Editorial standards</a><a href="https://github.com/omatty123/minds">Source &amp; revisions</a><span>Research checked 10 October 2026</span></div></footer></body></html>'''
 (OUT/file).write_text(doc)

def ref(id,label=None):
 d=next(x for x in DATA if x['id']==id)
 return f'<a href="bank.html#{id}">{E(label or d["title"])}</a>'

def source(id):
 d=next(x for x in DATA if x['id']==id)
 return f'<a href="{E(d["url"])}">Original source</a>'

home='''<section class="opening"><div class="lead"><h1>What is a mind?</h1><p class="standfirst">A shared study of thinking, feeling, making, and being.</p><p>MIND(s) proposes a common first-year encounter with one of the most consequential subjects of our time. It brings neuroscience into conversation with philosophy, Asian Studies, music, poetry, art, psychology, and sport.</p><p>Students would study minds through evidence, interpretation, and practice—and learn to write clearly about what remains unsettled.</p><div class="actions"><a class="button" href="syllabus.html">Read the model syllabus</a><a class="text-action" href="bank.html">Explore the learning bank <span aria-hidden="true">→</span></a></div></div><aside class="questions"><h2>The questions that begin it</h2><p>Why do we mind?</p><p>How do minds, sports, and art all interact?</p><p>What does it mean if we don’t know mind?</p><div class="status"><strong>Open for development</strong><span>A long-term proposal. An invitation to shape it.</span></div></aside></section>
<section class="front-section"><div class="section-heading"><h2>One theme. Many ways of knowing.</h2><a href="syllabus.html#sequence">See the ten-week sequence <span aria-hidden="true">→</span></a></div><div class="discipline-grid"><article><h3>Thinking &amp; feeling</h3><p>Neuroscience, philosophy and psychology distinguish attention, intelligence, affect and conscious experience. Students learn what each method can establish.</p></article><article><h3>Practice &amp; perception</h3><p>Asian Studies, sport and music bring trained action, cultivation, ensemble coordination and bodily experience into the center of the course.</p></article><article><h3>Form &amp; imagination</h3><p>Poetry and art develop their own accounts of experience. Close reading, listening and looking receive the same care as scientific interpretation.</p></article></div></section>
<section class="front-section"><div class="section-heading"><h2>Three starting points in current research</h2><a href="bank.html">Browse all sources <span aria-hidden="true">→</span></a></div><div class="research-leads">'''
for who,headline,desc,anchor in [('Michael Levin','Coordination beyond the brain','Cellular organization expands the study of cognition. The distinction between adaptive behavior and felt experience remains crucial.','levin-tissue'),('Mark Solms','Feeling at the center','An affect-centered account connects consciousness to bodily needs and uncertainty. Its extension to artificial agents is an active research claim.','solms-agent'),('Cameron Berg','Evidence from artificial systems','Mechanistic probes and model behavior make AI consciousness a concrete research problem. Self-report is a finding to examine, not a verdict.','berg-pain')]:
 home+=f'<article><h3>{who}</h3><h4><a href="bank.html#{anchor}">{headline}</a></h4><p>{desc}</p><a class="small-link" href="bank.html?researcher={who.replace(" ","+")}">Read the sources</a></article>'
home+='''</div><p class="editor-note">These are initial research priorities. The learning bank also includes competing theories, empirical tests, and cultural works. Inclusion does not imply agreement or endorsement.</p></section>
<section class="case-section"><div><h2>A liberal arts course about the minds doing the learning.</h2><p>The strongest case for MIND(s) is curricular: students can practice several kinds of inquiry on a shared subject that matters to their own intellectual lives.</p><p>A musician can bring the structure of a performance. An athlete can bring trained perception. A poet can bring an exact distinction that ordinary language misses. A scientist can bring a testable prediction. Each contribution changes the conversation.</p><p>The model preserves a common set of works and a progression from accurate summary to evidence-based argument. It treats disagreement as something to describe precisely.</p></div><aside><h3>A possible planning horizon</h3><p>Lawrence’s June 2024 announcement describes Water as a four-year theme beginning in fall 2024. That suggests a possible transition in <strong>fall 2028</strong>.</p><p>The transition date, proposal deadline and decision process still need confirmation.</p><a href="https://www.lawrence.edu/articles/water-initial-theme-first-year-studies-gets-makeover/">Read the institutional announcement</a></aside></section>
<section class="closing"><h2>Build something colleagues can teach together.</h2><p>The next step is to test the works, improve the sequence, and invite disciplinary expertise into the proposal.</p><a class="button" href="participate.html">Contribute to MIND(s)</a></section>'''
page('index.html','A shared study of minds',home)

core=''.join(f'<li><strong>{E(d["author"])}</strong><a href="bank.html#{d["id"]}">{E(d["title"])}</a></li>' for d in DATA if d['core'])
weeks=[
('Naming mind','dickinson','Read Dickinson’s complete poem. Introduce working distinctions among mind, brain, cognition, consciousness and affect.','Analyze the poem’s comparisons, syntax and scale.','Compare literary interpretation with a scientific claim.','Draft a 300-word accurate account of one passage.'),
('Feeling and explanation','solms-hard-problem','Read Solms’s abstract and introduction; faculty guide the technical vocabulary.','Map an argument from bodily needs to conscious feeling.','Compare supporting observations with theoretical conclusions.','Submit a 500-word claim-and-evidence summary.'),
('Skill and cultivated attention','zhuangzi','Read chapter 3 in Chinese Text Project’s translation; identify the translator and historical context.','Analyze Cook Ding’s practiced action and moments of caution.','Compare the narrative with the basketball-attention review’s abstract.','Prepare an evidence table: textual details and empirical measures.'),
('Music and shared timing','reich','Listen to a complete authorized recording of Music for 18 Musicians before class.','Describe two passages using timestamps, pulse, timbre and audible change.','Hold a proposed musician-led session on ensemble coordination.','Submit a 900-word close analysis of one core work.'),
('Art as an encounter','clark','Read MoMA’s Clark essay, concentrating on Caminhando and its historical setting.','Analyze documentation of the work as object, action and experience.','Compare Clark with the course’s accounts of embodied skill.','Revise the close analysis after peer and instructor feedback.'),
('Coordination across scales','levin-tissue','Read the author summary, abstract and Figure 1 caption of the tissue study.','Trace the movement from calcium imaging to a network representation.','Compare the finding with Levin and Resnik’s broader theoretical abstract.','Submit a 1,100-word comparison across two disciplines.'),
('Testing an account','cogitate','Read the COGITATE abstract and an instructor-prepared guide to the tested predictions.','Compare predictions, measurements and limitations.','Hold a proposed interdisciplinary panel on evidence and interpretation.','Submit a final-essay claim with three annotated sources.'),
('Artificial minds','berg-self-report','Read Berg and colleagues’ abstract, then instructor-selected results and limitations.','Compare model self-report with mechanistic evidence.','Read Seth’s abstract as a competing theoretical position.','Draft a counterargument and identify the evidence needed to assess it.'),
('Responsibility under uncertainty','butlin','Read the introduction or abstract of the Butlin report; faculty select a short indicator passage.','Compare uncertainty about experience with reasons for moral consideration.','Present a five-minute account of an argument using two disciplinary methods.','Bring a complete final-essay draft for peer review.'),
('Making a defensible argument','dickinson','Return to the opening poem and revisit the course vocabulary.','Workshop claims, source use and unresolved objections.','Hold a proposed concluding colloquium across sections.','Submit a 1,600–2,000-word revised essay and a 400-word revision account.')]
rows=''
for n,(title,id,a,b,c,work) in enumerate(weeks,1):
 rows+=f'<article class="week"><div class="week-label">Week {n}</div><div><h3>{title}</h3><p class="week-source">Starting work: {ref(id)}</p><ol class="meetings"><li>{a}</li><li>{b}</li><li>{c}</li></ol><p class="writing"><strong>Writing:</strong> {work}</p></div></article>'
syllabus=f'''<div class="page-title"><h1>Model syllabus</h1><p class="standfirst">MIND(s): thinking, feeling, and ways of knowing.</p><p>A ten-week faculty discussion draft. Seven shared works, supported by short research companions. Designed for three class meetings a week; dates, policies, exact excerpts and common events remain to be agreed.</p><div class="actions"><button class="button print-button" type="button">Print this syllabus</button><a href="#sequence">Go to the weekly sequence</a></div></div>
<div class="syllabus-intro"><section><h2>Course description</h2><p>This course studies minds through scientific explanation, philosophical argument, artistic form and embodied practice. Students examine the relationship between thinking and feeling, the development of skill, the interpretation of experience, and the limits of claims about other minds.</p><p>The course begins with a poem and moves among texts, music, art and experiments. Recent research by Michael Levin, Mark Solms and Cameron Berg supplies specific claims to assess alongside competing accounts. Students learn to distinguish a work’s meaning, a theory’s argument and a study’s findings.</p><h2>Learning outcomes</h2><ul class="outcomes"><li>Distinguish cognition, consciousness, attention and affect in a specific source.</li><li>Summarize a claim accurately and identify its supporting evidence.</li><li>Analyze a text, musical passage or artwork through details of its form.</li><li>Compare two disciplinary methods without treating them as equivalent.</li><li>Develop and revise an argument that addresses a substantive counterargument.</li></ul></section><aside class="core"><h2>Seven shared works</h2><ol>{core}</ol><p class="small">Supporting sources appear in the weekly sequence. The linked bank records explain access and evidence limits.</p></aside></div>
<section id="sequence"><div class="section-heading"><h2>The weekly sequence</h2><span>Three meetings per week · proposed</span></div>{rows}</section>
<section class="assessment"><h2>A writing sequence with room to revise</h2><p>Proposed assessment model, for discussion with the program: the final essay develops from earlier work. These percentages and lengths are draft choices, not current Lawrence policy.</p><div class="table-wrap"><table><thead><tr><th>Work</th><th>Purpose</th><th>Weight</th></tr></thead><tbody><tr><td>Short-writing portfolio</td><td>Accurate summary, evidence tables and preparatory writing</td><td>15%</td></tr><tr><td>Close analysis + revision</td><td>Explain how a core work produces meaning</td><td>20%</td></tr><tr><td>Comparative essay</td><td>Compare two methods and their limits</td><td>20%</td></tr><tr><td>Final essay + revision account</td><td>Defend a claim, use sources and address an objection</td><td>30%</td></tr><tr><td>Preparation, contribution + peer review</td><td>Support shared inquiry through spoken, written or other agreed accessible contributions</td><td>15%</td></tr></tbody></table></div><p>Across assignments, assess accuracy, use of specific evidence, quality of reasoning, organization and revision. Students are assessed on their arguments, not agreement with a theory of mind.</p></section>
<section class="implementation"><h2>Preparing this model for a real class</h2><div class="two-col"><div><h3>Reading and teaching support</h3><p>Use short scientific passages with a glossary and figure guide. The full technical papers belong in faculty preparation and optional extension. Confirm recording access and choose the precise translated editions before setting the common syllabus.</p><p>Plan a sustainable workload around the institution’s credit expectations. Pilot the proposed excerpts with first-year readers before fixing page counts. A laboratory or coding background is not a prerequisite for this model.</p></div><div><h3>Access and classroom practice</h3><p>Provide accessible texts, transcripts and visual descriptions. Offer equivalent ways to complete listening, movement and performance-based work. Personal health history or intimate self-disclosure is never required.</p><p>Before adoption, insert the current institutional policies on accommodations, academic integrity, attendance, late work and AI use. Any use of AI in assessed work needs a clear, shared policy and an accurate record of assistance.</p></div></div><p class="editor-note">Next curriculum review: expand Asian traditions beyond one Chinese text; consider a longer literary work; review global and demographic breadth; test whether the science selections are manageable. This is a concrete starting syllabus, not a completed selection process.</p></section>'''
page('syllabus.html','Model syllabus',syllabus)

def options(values):
 return ''.join(f'<option value="{E(x)}">{E(x)}</option>' for x in sorted(set(values)))
entries=''
for d in DATA:
 terms=' '.join([d['title'],d['author'],d['claim'],d['limit'],d['use'],*d['topics']])
 entries+=f'''<article class="bank-entry" id="{d['id']}" data-researcher="{E(d['focus'])}" data-kind="{E(d['kind'])}" data-topics="{E('|'.join(d['topics']))}" data-search="{E(terms.lower())}" data-date="{E(d['date'])}"><div class="entry-meta"><span class="evidence-type">{d['kind']}</span><span>{d['date']}</span>{'<span class="core-label">Shared work</span>' if d['core'] else ''}</div><div class="entry-body"><h2><a href="{E(d['url'])}">{E(d['title'])}</a></h2><p class="byline">{E(d['author'])}</p><p>{E(d['claim'])}</p><details><summary>Teaching use &amp; evidence notes</summary><div class="entry-notes"><p><strong>Teaching use</strong> {E(d['use'])}</p><p><strong>Limit</strong> {E(d['limit'])}</p><p><strong>Access</strong> {E(d['access'])}.</p><p><strong>Review depth</strong> {E(d['review'])}. Checked {d['checked']}.</p><div class="entry-links"><a href="{E(d['url'])}">Open source</a><a href="bank.html#{d['id']}">Link to this entry</a></div></div></details><p class="topics">{' · '.join(d['topics'])}</p></div></article>'''
bank=f'''<div class="page-title"><h1>Learning bank</h1><p class="standfirst">Research to examine. Works to teach. Claims to test.</p><p>A selected starting collection of {len(DATA)} sources, with particular attention to Levin, Solms and Berg. Recent research sits beside foundational studies and cultural works. Each entry identifies what it can—and cannot—support.</p></div><section class="bank-controls" aria-label="Filter sources" hidden><div class="search"><label for="search">Search the collection</label><input type="search" id="search" placeholder="Try attention, feeling, music…" autocomplete="off"></div><div class="filters"><label>Researcher<select id="researcher"><option value="">All researchers</option>{options(d['focus'] for d in DATA)}</select></label><label>Discipline<select id="discipline"><option value="">All disciplines</option>{options(t for d in DATA for t in d['topics'])}</select></label><label>Source type<select id="kind"><option value="">All source types</option>{options(d['kind'] for d in DATA)}</select></label><button type="button" id="reset">Clear filters</button></div></section><div class="bank-count"><p id="result-count" role="status" aria-live="polite">{len(DATA)} sources</p><a href="bank.json" download>Download source data (JSON)</a></div><p id="empty" hidden>No sources match these filters. Try a broader term or clear the filters.</p><div class="bank-list">{entries}</div><section class="bank-scope"><h2>Scope of this edition</h2><p>Checked 10 October 2026. The collection draws on the Levin Lab publication list, Reciprocal Research’s listed outputs, selected Solms papers, original publication records and institutional cultural resources. It is a selected reading bank, not a systematic review or a complete research inventory.</p><p>Publication status and evidence type are separate: a peer-reviewed theoretical paper still presents a theory. An abstract-level check is identified as such. A source’s date does not imply that it is the newest work in its field.</p><p>Priority gaps include recent research on music and sport, a fuller range of Asian traditions, disability and neurodiversity scholarship, animal cognition, and a broader literary selection. Sources need deeper review and teaching trials before final adoption.</p><a href="participate.html#editorial">Read the editorial standards</a></section>'''
page('bank.html','Learning bank',bank)

participate='''<div class="page-title"><h1>Shape the proposal.</h1><p class="standfirst">A common course needs many kinds of expertise.</p><p>MIND(s) is an invitation to develop a teachable, interdisciplinary First-Year Studies theme. Colleagues can contribute a work, improve a research annotation, test a short unit, or help assess the proposed sequence.</p><a class="button" href="https://github.com/omatty123/minds/issues/new?title=Contribution%20to%20MIND(s)">Suggest a source or revision</a><p class="small">Submissions use public GitHub issues and require a GitHub account. Include a source link, a short rationale, and the proposed change. Please keep private correspondence and student information out of public submissions.</p></div><section><h2>Contributions that will move this forward</h2><div class="contribution-list"><article><h3>Recommend a teachable work</h3><p>Identify a specific text, artwork, recording or study. Give a manageable selection, an access route and a clear account of its contribution to the common course.</p></article><article><h3>Test a connection</h3><p>Develop a short comparison across two methods: musical timing and skilled movement, poetry and perception, cellular coordination and collective behavior, or cultivation and attention.</p></article><article><h3>Strengthen the evidence</h3><p>Add an important counterargument, a replication, a newer review or a clearer explanation of a study’s limits. Correct a record without treating disagreement as an error.</p></article></div></section><section class="case-section"><div><h2>Connections already available at Lawrence</h2><p>The <a href="https://lux.lawrence.edu/convocations/19/">2023 Catholic and Buddhist pilgrimage convocation by Madera Allan and Constance Kassor</a> offers a potential contribution through practice, movement, place and transformation. A MIND(s) unit could develop those connections while preserving the traditions’ histories and meanings.</p><p>Lawrence’s archive also includes <a href="https://lux.lawrence.edu/frst_lectures/112/">Madera Allan’s First-Year Studies lecture on Borges</a>. Literary treatments of memory and identity could strengthen a later syllabus revision.</p><p class="small">These are possible curricular connections drawn from public records. No participation or endorsement by the named faculty is implied.</p></div><aside><h3>Work in stages</h3><ol class="stages"><li><strong>Develop the case.</strong> Refine this syllabus and source bank with colleagues.</li><li><strong>Test a short unit.</strong> Gather evidence about reading load, accessibility and cross-disciplinary teaching.</li><li><strong>Confirm the process.</strong> Establish the actual theme-selection schedule, criteria and governance.</li><li><strong>Prepare the proposal.</strong> Submit a shared curriculum with works, access plans and teaching support.</li></ol></aside></section><section id="editorial"><h2>Editorial standards</h2><div class="two-col"><div><h3>Keep claims accountable</h3><p>Every research entry links a source and records its date, type, review depth and check date. Empirical observations, theoretical interpretations, preprints and cultural works retain their distinct roles.</p><p>We do not infer consciousness from complexity, successful performance or a model’s self-description alone. We also do not treat uncertainty as proof of absence. Competing accounts belong in the same collection.</p></div><div><h3>Keep the collection useful</h3><p>Teaching annotations identify a concrete use and a limit. Link to authorized texts and recordings. Preserve author names, translation context and the distinction between publication and endorsement.</p><p>This edition is manually curated. Its October 2026 check date is not an automatic updating service. Significant additions should receive a new check date and a revision note.</p></div></div></section><section class="closing"><h2>The first edition is a starting point.</h2><p>The purpose is to make the proposal specific enough to evaluate, teach from and improve.</p><a class="button" href="syllabus.html">Return to the model syllabus</a></section>'''
page('participate.html','Take part',participate)
shutil.copyfile(ROOT/'bank.json',OUT/'bank.json')
(OUT/'.nojekyll').touch()
(OUT/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="#bd1622"/><text x="32" y="46" font-family="Georgia,serif" font-weight="bold" font-size="45" fill="white" text-anchor="middle">M</text></svg>')
print('Built 4 pages and',len(DATA),'source entries.')
